// Assume 'oldfd' is a valid file descriptor

// dup(): Returns lowest available FD (same offset/flags)
int newfd = dup(oldfd);
// Returns new FD on success, -1 on error

// dup2(): Duplicates oldfd to targetfd
// Closes targetfd first if already open
int targetfd_2 = 10;
int res_2 = dup2(oldfd, targetfd_2);
// Returns targetfd_2 or -1 on error

// Common Use Case: Redirect STDOUT (FD 1)
dup2(oldfd, STDOUT_FILENO); 

// dup3(): Adds flags (Linux >= 2.6.27)
// O_CLOEXEC: Set close-on-exec flag
int targetfd_3 = 11;
int res_3 = dup3(oldfd, targetfd_3, O_CLOEXEC);

// dup3 Constraint:
// Fails with EINVAL if oldfd == newfd and flags == 0
if (oldfd == 5) {
    dup3(5, 5, 0); // Returns -1 (EINVAL)
}
